Q = []
def q(n, t, stem, opts, key, skill, level, ev, expl, expl_ru, kw_ok, notes, fixed=False):
    """notes: {letter: (kk, ru, [evidence], [kw kk], [kw ru])}"""
    Q.append({"id": f"l2v2-q{n}", "number": n, "text_id": f"l2v2-t{t}", "stem": stem,
              "options": dict(zip("ABCD", opts)), "key": key, "skill": skill, "skill_name": SKILLS[skill],
              "level": level, "negative": False, "fixed_order": fixed,
              "evidence": ev, "explanation": expl, "explanation_ru": expl_ru,
              "distractor_notes": {k: v[0] for k, v in notes.items()},
              "distractor_notes_ru": {k: v[1] for k, v in notes.items()},
              # Қате нұсқалардың дәлелі – таза сөйлем (азатжол/бөлім нөмірін платформа өзі анықтайды)
              "distractor_evidence": {k: [re.sub(r"\s*\([^)]*(азатжол|бөлім)[^)]*\)$", "", e) for e in v[2]] for k, v in notes.items()},
              "keywords": dict({"ok": {"kk": kw_ok[0], "ru": kw_ok[1]}},
                               **{k: {"kk": v[3], "ru": v[4]} for k, v in notes.items() if v[2]}),
              "editor_changes": ""})

