q(13, 6, "Шәкірт нені армандады?",
  ["ұстазынан озып, елге танымал ғұлама болуды", "күнде қырға шығып, әдемі көбелек аулауды", "ұстазына есте қалатын жақсы сыйлық жасауды", "ұстазы жауап бере алмайтын сұрақ қоюды"], "D", "A1", 1,
  ["Өмір бәсекесіз бола ма, осы шәкірттерінің бірі ұстазы жауап бере алмайтын сауал тауып қоюды армандапты."],
  "Шәкірт ұстазы жауап бере алмайтын сауал тауып қоюды армандаған. «Сауал» – сұрақ деген сөз.",
  "Ученик мечтал найти вопрос, на который учитель не сможет ответить. «Сауал» значит «вопрос».",
  (["ұстазы жауап бере алмайтын сауал", "армандапты"], ["вопрос, на который учитель не сможет ответить", "мечтал"]),
  {"A": ("мәтінде шәкірттің ғұлама болуды армандағаны айтылмайды. «Ғұлама» деп мәтінде ұстазды атайды.", "В тексте не сказано, что ученик мечтал стать учёным. «Ғұлама» в тексте называют учителя.",
         ["Ертеде бір топ шәкірті бар ғұлама өмір сүріпті."], ["ғұлама"], ["мудрец"]),
   "B": ("шәкірт көбелекті армандағаны үшін емес, ұстазына сұрақ қою үшін ұстады.", "Ученик поймал бабочку не потому, что мечтал о ней, а чтобы задать вопрос учителю.", [], [], []),
   "C": ("шәкірт көбелекті ұстазына сыйлық ретінде әкелмеді, оны алақанына жасырып, сұрақ қойды.", "Ученик принёс бабочку не в подарок: он спрятал её в ладони и задал вопрос.",
         ["– Ұстаз, айтыңызшы: менің қолымдағы тірі көбелек пе, өлі көбелек пе?"], ["тірі көбелек пе, өлі көбелек пе"], ["живая бабочка или мёртвая"])})

q(14, 6, "«Бәрі сенің қолыңда.»\nОсы сөйлемде ұстаз кімді атап тұр?", ["шәкіртті", "көбелекті", "ұстаздың өзін", "басқа шәкірттерді"], "A", "B1", 2,
  ["Шәкірт ұстаз жауабына орай көбелекті өлтіріп не ұшырып жіберуге даяр еді.", "– Бәрі сенің қолыңда."],
  "Ұстаз сұрақ қойған шәкіртке жауап беріп тұр. Көбелектің тірі не өлі болуы тек шәкіртке байланысты еді: ол көбелекті ұшырып та, өлтіріп те жібере алатын. Көбелек шынында да шәкірттің қолында тұр.",
  "Учитель отвечает ученику, который задал вопрос. Будет бабочка живой или мёртвой, зависело только от ученика: он мог и отпустить её, и убить. Бабочка и правда у ученика в руке.",
  (["Шәкірт", "өлтіріп не ұшырып жіберуге даяр", "сенің қолыңда"], ["Ученик", "был готов убить или отпустить", "в твоих руках"]),
  {"B": ("ұстаз көбелекпен сөйлесіп тұрған жоқ. Ол сұрақ қойған адамға жауап береді.", "Учитель не разговаривает с бабочкой — он отвечает тому, кто задал вопрос.", [], [], []),
   "C": ("«сенің» – екінші жақ, яғни сөйлеуші емес, тыңдаушы. Ұстаз өзі туралы айтса, «менің» дер еді.", "«Сенің» (твой) — второе лицо, то есть слушатель, а не говорящий. О себе учитель сказал бы «менің» (мой).", [], [], []),
   "D": ("«сенің» – бір адамға айтылған сөз. Ұстаз сұрақты бір шәкірттен ғана естіді.", "«Сенің» (твой) обращено к одному человеку. Учитель услышал вопрос только от одного ученика.",
         ["Өмір бәсекесіз бола ма, осы шәкірттерінің бірі ұстазы жауап бере алмайтын сауал тауып қоюды армандапты."], ["шәкірттерінің бірі"], ["из его учеников"])})

q(15, 6, "Бос орынға қай сөз қойылады?", ["Сол үшін", "Сонда да", "Керісінше", "Сондай-ақ"], "A", "C4", 3,
  ["Өмір бәсекесіз бола ма, осы шәкірттерінің бірі ұстазы жауап бере алмайтын сауал тауып қоюды армандапты."],
  "Шәкірт ұстазына қиын сұрақ қоюды армандады, сондықтан көбелек ұстап келді. Екінші сөйлем біріншісінің мақсатын, нәтижесін айтады. Оны «сол үшін» байланыстырады.",
  "Ученик мечтал задать учителю трудный вопрос, поэтому поймал бабочку. Второе предложение говорит о цели и следствии первого — его связывает «сол үшін» (для этого, поэтому).",
  (["сауал тауып қоюды армандапты"], ["мечтал найти вопрос"]),
  {"B": ("«сонда да» – «соған қарамастан» деген мағынада, қарама-қарсы ойды байланыстырады. Ал мұнда шәкірт арманын орындау үшін әрекет етеді, қарсылық жоқ.", "«Сонда да» (и всё же, несмотря на это) связывает противоположные мысли. А здесь ученик действует, чтобы исполнить мечту, — противопоставления нет.", [], [], []),
   "C": ("«керісінше» алдыңғы ойға қарсы әрекетті білдіреді. Шәкірт армандағанына қарсы емес, сол арманы үшін әрекет етті.", "«Керісінше» (наоборот) означает действие вопреки сказанному. Ученик действовал не вопреки мечте, а ради неё.", [], [], []),
   "D": ("«сондай-ақ» жаңа, қосымша ақпаратты қосады. Ал мұнда екінші сөйлем жаңа ақпарат емес, шәкірттің арманына жету үшін не істегенін айтады.", "«Сондай-ақ» (а также) добавляет новую информацию. А здесь второе предложение рассказывает, что ученик сделал ради своей мечты.", [], [], [])})

