q(16, 7, "Мәтіндегі оқиғалардың реті қандай?\n1. Нан тасыған құмырсқа\n2. Атасының ақылы\n3. Өрмек тоқыған өрмекші\n4. Шөп тасыған қарлығаш",
  ["1, 3, 4, 2", "3, 1, 2, 4", "3, 1, 4, 2", "3, 4, 1, 2"], "C", "C4", 2,
  ["— Көремін, өрмек тоқып жүр.", "— Көремін, аузында бір нанның уалшығы бар, жүгіріп кетіп барады.",
   "— Жоғарыда қарлығаш ұшып жүр, аузында кесе тістеген шөбі бар.", "Жұмыссыз жүрген бір жан жоқ."],
  "Алдымен бала өрмек тоқыған өрмекшіні көреді (3), сосын нан тасыған құмырсқаны (1), кейін шөп тістеген қарлығашты (4), соңында атасы ақыл айтады (2).",
  "Сначала мальчик видит паука, плетущего паутину (3), потом муравья с хлебной крошкой (1), затем ласточку с травинкой (4), и в конце дед даёт совет (2).",
  (["өрмек тоқып жүр", "нанның уалшығы", "қарлығаш ұшып жүр", "Жұмыссыз жүрген бір жан жоқ"], ["плетёт паутину", "хлебная крошка", "летает ласточка", "Нет ни одного существа без дела"]),
  {"A": ("атасы алдымен құмырсқаны емес, басқа жәндікті көрсетті. Атасының бірінші сұрағын қайта оқы.", "Дед сначала показал не муравья, а другое существо. Перечитай первый вопрос деда.", [], [], []),
   "B": ("атасы ақылды ең соңында, үш жәндікті де көрсеткен соң айтады.", "Дед даёт совет в самом конце, после того как показал всех троих.",
         ["Сонда атасы айтты:"], ["Сонда атасы айтты"], ["Тогда дед сказал"]),
   "D": ("алғашқы оқиға дұрыс. Ал қарлығашты бала аспаннан ең соңында көрді, оған дейін жерде құмырсқаны көрді.", "Первое событие верно. Но ласточку в небе мальчик увидел последней, а до неё — муравья на земле.",
         ["— Жоғары қара, аспанда не көрінеді?"], ["Жоғары қара"], ["Посмотри наверх"])}, fixed=True)

q(17, 7, "Бос орынға қай жауап сәйкес келеді?",
  ["атаңа көп сұрақ қою керек", "жәндіктерге қамқор болу керек", "далада көбірек серуендеп жүру керек", "жұмыс істеуге әдеттену керек"], "D", "C4", 3,
  ["Жұмыссыз жүрген бір жан жоқ.", "Сені де Құдай-Тағала бос жүруге жаратпаған"],
  "Атасы өрмекші, құмырсқа, қарлығаштың бәрі жұмыс істеп жүргенін көрсетіп, «Жұмыссыз жүрген бір жан жоқ» дейді. «Сені де … бос жүруге жаратпаған» деген сөзден кейін еңбекке шақыру келуі керек.",
  "Дед показывает, что паук, муравей и ласточка — все трудятся, и говорит: «Нет ни одного существа без дела». После слов «и ты создан не для безделья» должен следовать призыв к труду.",
  (["Жұмыссыз жүрген бір жан жоқ", "бос жүруге жаратпаған"], ["Нет ни одного существа без дела", "не для того, чтобы бездельничать"]),
  {"A": ("бала атасының сұрақтарына жауап береді, атасы оны сұрақ қоюға шақырмайды. Атасы жәндіктердің не істеп жүргеніне назар аударады.", "Мальчик отвечает на вопросы деда, а дед не призывает его задавать вопросы. Дед обращает внимание на то, чем заняты насекомые.", [], [], []),
   "B": ("атасы жәндіктерге қамқор бол демейді, оларды үлгі етіп көрсетеді.", "Дед не призывает заботиться о насекомых — он ставит их в пример.",
         ["— Олай болса, шырағым, ол кішкентай жәндіктер саған әбірет."], ["саған әбірет"], ["тебе пример"]),
   "C": ("атасы мен бала далада келе жатыр, бірақ атасы серуендеуге шақырмайды. Ол «бос жүру» туралы не дейтінін қайта оқы.", "Дед и мальчик идут по степи, но дед не зовёт гулять. Перечитай, что он говорит о «бос жүру» (безделье).",
         ["Атасы он жасар ұл баласымен далада келе жатып, баласынан сұрады:"], ["далада келе жатып"], ["идя по степи"])})

