q(20, 9, "Мәтіннің негізгі ойы қандай?",
  ["Тойға әрқашан жаңа, әдемі киіммен бару керек.", "Үй иесі қонақты әрқашан етпен сыйлауы керек.", "Тойға келген әр қонақ сыйлық әкелуі керек.", "Адамды киіміне қарап бағалау дұрыс емес."], "D", "C1", 2,
  ["Қожанасырдың үстіндегі киімі жаман екен.", "Бұл жолы үй иесі Қожанасырды құрметтейді, төрден орын береді, ет келгенде:",
   "– Сен кісіні сыйламайды екенсің, киімді сыйлайды екенсің."],
  "Қожанасыр жаман киіммен келгенде, оны ешкім елемеді. Тәуір киім киіп келгенде, құрметтеді. Қожанасыр «кісіні емес, киімді сыйлайды екенсің» деп, адамды киіміне қарап бағалаудың дұрыс емес екенін көрсетті.",
  "Когда Ходжа пришёл в плохой одежде, его никто не замечал, а когда пришёл в хорошей — его стали почитать. Словами «уважаешь не человека, а одежду» Ходжа показал, что судить о человеке по одежде неправильно.",
  (["киімі жаман", "Бұл жолы", "құрметтейді", "кісіні сыйламайды", "киімді сыйлайды"], ["была плохой", "На этот раз", "оказывает почёт", "не уважаешь человека", "уважаешь одежду"]),
  {"A": ("Қожанасыр жаңа киім кигені үшін емес, адамдарға сабақ болу үшін киімін ауыстырды.", "Ходжа переоделся не ради новой одежды, а чтобы преподать людям урок.",
         ["Сондықтан шапаныма жегізіп отырғаным!"], ["шапаныма жегізіп"], ["кормлю свой халат"]),
   "B": ("мәтінде қонаққа ет беріледі, бірақ негізгі ой – ет туралы емес. Қожанасырдың соңғы сөзін қайта оқы.", "В тексте гостя угощают мясом, но главная мысль не о мясе. Перечитай последние слова Ходжи.", [], [], []),
   "C": ("мәтінде сыйлық туралы айтылмайды.", "В тексте ничего не сказано о подарках.", [], [], [])})

